const taskSeed: TaskItem[] = [{ id: 't1', title: 'Review Q3 enterprise pipeline', due: 'Today, 10:00 AM', priority: 'High', assignee: 'AR', status: 'In progress', record: 'Pipeline' }, { id: 't2', title: 'Follow up with Northstar Labs', due: 'Today, 2:30 PM', priority: 'Medium', assignee: 'JC', status: 'To do', record: 'Northstar Labs' }, { id: 't3', title: 'Send proposal to Circooles', due: 'Tomorrow', priority: 'High', assignee: 'SL', status: 'To do', record: 'Circooles' }, { id: 't4', title: 'Prepare weekly forecast', due: 'Oct 29', priority: 'Low', assignee: 'AR', status: 'To do', record: 'Reports', recurring: 'Every week' }]
function TasksView({ completedTasks, setCompletedTasks, notify }: { completedTasks: string[]; setCompletedTasks: React.Dispatch<React.SetStateAction<string[]>>; notify: (v: string) => void }) { const [mode, setMode] = useState<'List' | 'Kanban'>('List'); const [filter, setFilter] = useState('All'); const [tasks, setTasks] = useState(taskSeed); const visible = tasks.filter((task) => filter === 'All' || task.priority === filter); const toggle = (task: TaskItem) => { const next = task.status === 'Done' ? 'To do' : 'Done'; setTasks((current) => current.map((item) => item.id === task.id ? { ...item, status: next } : item)); setCompletedTasks((current) => next === 'Done' ? [...current, task.title] : current.filter((item) => item !== task.title)); notify(next === 'Done' ? 'Task completed' : 'Task reopened') }; return <div className="p-5 lg:p-8"><PageHeader eyebrow="Manage" title="Tasks" description="Stay on top of your team's priorities" action="Add task" onAction={() => notify('Task creation form opened')} /><div className="mb-5 grid gap-3 sm:grid-cols-3">{[['My open tasks', String(tasks.filter((t) => t.status !== 'Done').length), '4 due today'], ['Completed this week', '28', '+14% vs last week'], ['Overdue', '1', 'Needs attention']].map(([label, value, sub]) => <div key={String(label)} className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs text-slate-500">{String(label)}</p><p className="mt-2 text-2xl font-semibold">{value}</p><p className="mt-1 text-[11px] text-slate-400">{sub}</p></div>)}</div><div className="mb-4 flex flex-wrap gap-2"><div className="flex rounded-lg border border-slate-200 bg-white p-1">{['List', 'Kanban'].map((item) => <button key={item} onClick={() => setMode(item as 'List' | 'Kanban')} className={`rounded-md px-3 py-1.5 text-xs font-medium ${mode === item ? 'bg-slate-100 text-slate-900' : 'text-slate-500'}`}>{item}</button>)}</div><select value={filter} onChange={(e) => setFilter(e.target.value)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-xs"><option>All</option><option>High</option><option>Medium</option><option>Low</option></select><button onClick={() => notify('Reminder settings opened')} className="flex h-9 items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 text-xs"><Bell className="size-3.5" />Reminders</button><button onClick={() => notify('Recurring task configuration opened')} className="flex h-9 items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 text-xs"><RefreshCw className="size-3.5" />Recurring</button></div>{mode === 'List' ? <div className="rounded-xl border border-slate-200 bg-white shadow-sm">{visible.map((task) => <div key={task.id} className="flex items-center gap-4 border-b border-slate-100 px-5 py-4 last:border-0"><button onClick={() => toggle(task)} className={`flex size-5 items-center justify-center rounded-full border ${task.status === 'Done' ? 'border-emerald-500 bg-emerald-500 text-white' : 'border-slate-300'}`}>{task.status === 'Done' && <Check className="size-3" />}</button><div className="min-w-0 flex-1"><p className={`text-sm font-medium ${task.status === 'Done' ? 'text-slate-400 line-through' : ''}`}>{task.title}</p><p className={`mt-1 text-xs ${task.due.includes('23') ? 'text-rose-500' : 'text-slate-400'}`}>{task.due} · {task.priority} priority · {task.record}</p></div><span className="rounded-full bg-slate-100 px-2 py-1 text-[10px] font-medium text-slate-500">{task.assignee}</span></div>)}</div> : <div className="grid gap-4 lg:grid-cols-3">{(['To do', 'In progress', 'Done'] as const).map((status) => <div key={status} className="rounded-xl bg-slate-100/70 p-3"><h2 className="mb-3 text-xs font-semibold">{status}</h2><div className="flex flex-col gap-3">{visible.filter((task) => task.status === status).map((task) => <button key={task.id} onClick={() => toggle(task)} className="rounded-lg border border-slate-200 bg-white p-3 text-left shadow-sm"><p className="text-sm font-medium">{task.title}</p><p className="mt-2 text-xs text-slate-400">{task.due} · {task.record}</p><span className="mt-3 inline-block rounded-full bg-indigo-50 px-2 py-1 text-[10px] text-indigo-600">{task.priority}</span></button>)}</div></div>)}</div>}</div> }
function CalendarView({ notify }: { notify: (v: string) => void }) { const [mode, setMode] = useState('Month'); const [date, setDate] = useState(new Date(2026, 9, 26)); const events = [{ title: 'Pipeline review', time: '10:00 AM', type: 'Meeting' }, { title: 'Call with Northstar Labs', time: '2:30 PM', type: 'Call' }, { title: 'Proposal deadline', time: '5:00 PM', type: 'Deadline' }]; const days = Array.from({ length: 35 }, (_, i) => i - 3); return <div className="p-5 lg:p-8"><PageHeader eyebrow="Manage" title="Calendar" description="Plan meetings, calls, deadlines, and follow-ups" action="Add event" onAction={() => notify('Event form opened')} /><div className="mb-4 flex flex-wrap items-center gap-2"><button onClick={() => setDate(new Date(2026, 9, 26))} className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-medium">Today</button><button onClick={() => setDate(new Date(date.getFullYear(), date.getMonth(), date.getDate() - 7))} className="flex size-9 items-center justify-center rounded-lg border border-slate-200 bg-white"><ChevronLeft className="size-4" /></button><button onClick={() => setDate(new Date(date.getFullYear(), date.getMonth(), date.getDate() + 7))} className="flex size-9 items-center justify-center rounded-lg border border-slate-200 bg-white"><ChevronRight className="size-4" /></button><h2 className="ml-2 text-sm font-semibold">October 2026</h2><div className="ml-auto flex rounded-lg border border-slate-200 bg-white p-1">{['Month', 'Week', 'Day', 'Agenda'].map((item) => <button key={item} onClick={() => setMode(item)} className={`rounded-md px-3 py-1.5 text-xs ${mode === item ? 'bg-slate-100 font-semibold' : 'text-slate-500'}`}>{item}</button>)}</div><button onClick={() => notify('Calendar filters opened')} className="flex h-9 items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 text-xs"><Filter className="size-3.5" />Filters</button></div>{mode === 'Agenda' ? <div className="rounded-xl border border-slate-200 bg-white shadow-sm">{events.map((event) => <button key={event.title} onClick={() => notify(`${event.title} opened`)} className="flex w-full items-center gap-4 border-b border-slate-100 p-5 text-left last:border-0"><div className="flex size-10 items-center justify-center rounded-xl bg-indigo-50 text-indigo-600"><CalendarDays className="size-4" /></div><div><p className="text-sm font-semibold">{event.title}</p><p className="mt-1 text-xs text-slate-400">Oct 26 · {event.time} · {event.type}</p></div><ChevronRight className="ml-auto size-4 text-slate-300" /></button>)}</div> : <div className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><div className="grid grid-cols-7 gap-2 text-center text-[10px] font-semibold uppercase tracking-wider text-slate-400">{['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map((day) => <span key={day} className="py-2">{day}</span>)}{days.map((day, index) => <button key={index} onClick={() => notify(`New event on October ${day}`)} className={`min-h-20 rounded-lg border p-2 text-left text-xs ${day === 26 ? 'border-indigo-400 bg-indigo-50' : 'border-slate-100 hover:border-indigo-200'}`}><span className={day < 1 || day > 31 ? 'text-slate-300' : 'font-medium'}>{day < 1 ? day + 31 : day > 31 ? day - 31 : day}</span>{day === 26 && <div className="mt-2 rounded bg-indigo-600 px-1.5 py-1 text-[10px] text-white">2 events</div>}{day === 27 && <div className="mt-2 rounded bg-amber-50 px-1.5 py-1 text-[10px] text-amber-700">Deadline</div>}</button>)}</div></div>}</div> }
function ActivitiesView({ notify }: { notify: (v: string) => void }) { const [type, setType] = useState('All'); const [items, setItems] = useState<ActivityItem[]>([{ id: 'a1', type: 'Call', title: 'Discovery call completed', person: 'Phoenix Baker', company: 'Northstar Labs', date: 'Today, 9:42 AM', owner: 'JC', detail: 'Discussed migration timeline and technical requirements.' }, { id: 'a2', type: 'Email', title: 'Proposal follow-up sent', person: 'Olivia Rhye', company: 'Quartz & Co.', date: 'Yesterday, 4:10 PM', owner: 'AR', detail: 'Sent enterprise expansion proposal and pricing options.' }, { id: 'a3', type: 'Meeting', title: 'Quarterly business review', person: 'Candice Wu', company: 'Circooles', date: 'Oct 23, 2:00 PM', owner: 'SL', detail: 'Reviewed adoption metrics and renewal plan.' }, { id: 'a4', type: 'Task', title: 'Task completed', person: 'Lana Steiner', company: 'Velocity', date: 'Oct 22, 11:30 AM', owner: 'MK', detail: 'Updated account plan.' }]); const shown = items.filter((item) => type === 'All' || item.type === type); return <div className="p-5 lg:p-8"><PageHeader eyebrow="Engage" title="Activities" description="A chronological view of every customer touchpoint" action="Log activity" onAction={() => notify('Activity form opened')} /><div className="mb-4 flex flex-wrap gap-2">{['All', 'Call', 'Email', 'Meeting', 'Note', 'Task'].map((item) => <button key={item} onClick={() => setType(item)} className={`rounded-lg border px-3 py-2 text-xs font-medium ${type === item ? 'border-indigo-200 bg-indigo-50 text-indigo-700' : 'border-slate-200 bg-white text-slate-500'}`}>{item}</button>)}<button onClick={() => notify('Activity filters opened')} className="ml-auto flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs text-slate-600"><Filter className="size-3.5" />Filters</button></div><div className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="relative ml-3 border-l border-slate-200">{shown.map((item) => <div key={item.id} className="relative pb-7 pl-8 last:pb-1"><span className="absolute -left-2 top-0 flex size-4 items-center justify-center rounded-full border-2 border-white bg-indigo-500 ring-1 ring-indigo-200" /><div className="flex flex-col gap-1 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-sm font-semibold">{item.title}</p><p className="mt-1 text-xs text-slate-500">{item.person} · {item.company}</p><p className="mt-2 max-w-xl text-xs leading-5 text-slate-400">{item.detail}</p></div><span className="text-[11px] text-slate-400">{item.date}</span></div></div>)}</div><button onClick={() => { setItems((current) => [{ id: `a${current.length + 1}`, type: 'Note', title: 'Internal note logged', person: 'Ahmed Raza', company: 'Workspace', date: 'Just now', owner: 'AR', detail: 'Follow-up note added from the activities timeline.' }, ...current]); notify('Note logged') }} className="mt-6 flex items-center gap-2 rounded-lg bg-indigo-600 px-3 py-2 text-xs font-semibold text-white"><Plus className="size-3.5" />Log note</button></div></div> }

function InboxView({ notify }: { notify: (v: string) => void }) {
  const [items, setItems] = useState(conversationSeed)
  const [selectedId, setSelectedId] = useState('c1')
  const [filter, setFilter] = useState<'All' | Conversation['status']>('All')
  const [query, setQuery] = useState('')
  const [reply, setReply] = useState('')
  const selected = items.find((item) => item.id === selectedId) || items[0]
  const visible = items.filter((item) => (filter === 'All' || item.status === filter) && `${item.customer} ${item.company} ${item.subject}`.toLowerCase().includes(query.toLowerCase()))
  const send = (event: React.FormEvent) => { event.preventDefault(); if (!reply.trim()) return; setItems((current) => current.map((item) => item.id === selected.id ? { ...item, messages: [...item.messages, { from: 'Ahmed Raza', text: reply.trim(), time: 'Just now' }], updated: 'Just now', unread: false } : item)); setReply(''); notify('Reply sent') }
  return <div className="p-5 lg:p-8"><PageHeader eyebrow="Engage" title="Communication inbox" description="Keep every customer conversation moving forward" action="New conversation" onAction={() => notify('New conversation form opened')} /><div className="grid min-h-[640px] overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm lg:grid-cols-[280px_minmax(0,1fr)_260px]"><section className="border-b border-slate-200 lg:border-b-0 lg:border-r"><div className="border-b border-slate-100 p-4"><div className="relative"><Search className="absolute left-3 top-2.5 size-4 text-slate-400" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search conversations" className="h-9 w-full rounded-lg border border-slate-200 bg-slate-50 pl-9 pr-3 text-xs outline-none focus:border-indigo-400" /></div><div className="mt-3 flex gap-1 overflow-x-auto">{['All', 'Open', 'Pending', 'Resolved'].map((item) => <button key={item} onClick={() => setFilter(item as typeof filter)} className={`whitespace-nowrap rounded-md px-2 py-1.5 text-[11px] font-medium ${filter === item ? 'bg-indigo-50 text-indigo-700' : 'text-slate-500 hover:bg-slate-50'}`}>{item}</button>)}</div></div><div className="divide-y divide-slate-100">{visible.map((item) => <button key={item.id} onClick={() => { setSelectedId(item.id); setItems((current) => current.map((row) => row.id === item.id ? { ...row, unread: false } : row)) }} className={`w-full p-4 text-left hover:bg-slate-50 ${selected.id === item.id ? 'bg-indigo-50/60' : ''}`}><div className="flex items-start gap-3"><div className="flex size-8 shrink-0 items-center justify-center rounded-full bg-indigo-100 text-[10px] font-semibold text-indigo-700">{initials(item.customer)}</div><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><p className={`truncate text-xs ${item.unread ? 'font-bold' : 'font-medium'}`}>{item.customer}</p><span className="text-[10px] text-slate-400">{item.updated}</span></div><p className="mt-1 truncate text-[11px] font-medium text-slate-600">{item.subject}</p><div className="mt-2 flex items-center gap-1.5"><span className={`size-1.5 rounded-full ${item.status === 'Open' ? 'bg-emerald-500' : item.status === 'Pending' ? 'bg-amber-500' : 'bg-slate-300'}`} /><span className="text-[10px] text-slate-400">{item.status}</span>{item.priority === 'High' && <span className="rounded bg-rose-50 px-1.5 py-0.5 text-[9px] font-semibold text-rose-600">Priority</span>}</div></div></div></button>)}{visible.length === 0 && <p className="p-8 text-center text-xs text-slate-400">No conversations found.</p>}</div></section><section className="flex min-h-[580px] flex-col"><div className="flex items-center justify-between border-b border-slate-100 p-4"><div><p className="text-sm font-semibold">{selected.subject}</p><p className="mt-1 text-xs text-slate-400">{selected.customer} · {selected.company} · {selected.channel}</p></div><div className="flex items-center gap-2"><button onClick={() => notify('Conversation assigned to Ahmed')} className="rounded-lg border border-slate-200 px-3 py-2 text-xs font-medium text-slate-600">Assign</button><button onClick={() => { setItems((current) => current.map((item) => item.id === selected.id ? { ...item, status: item.status === 'Resolved' ? 'Open' : 'Resolved' } : item)); notify(selected.status === 'Resolved' ? 'Conversation reopened' : 'Conversation resolved') }} className="rounded-lg bg-indigo-600 px-3 py-2 text-xs font-semibold text-white">{selected.status === 'Resolved' ? 'Reopen' : 'Resolve'}</button></div></div><div className="flex-1 space-y-4 overflow-y-auto bg-slate-50/60 p-5">{selected.messages.map((message, index) => <div key={`${message.time}-${index}`} className={`flex ${message.internal ? 'justify-center' : message.from === 'Ahmed Raza' ? 'justify-end' : 'justify-start'}`}><div className={`max-w-[78%] rounded-2xl px-4 py-3 text-sm ${message.internal ? 'bg-amber-50 text-amber-800' : message.from === 'Ahmed Raza' ? 'rounded-br-md bg-indigo-600 text-white' : 'rounded-bl-md border border-slate-200 bg-white text-slate-700'}`}><p className="text-[10px] font-semibold opacity-70">{message.internal ? 'Internal note' : message.from}</p><p className="mt-1 leading-6">{message.text}</p><p className="mt-2 text-[10px] opacity-60">{message.time}</p></div></div>)}</div><form onSubmit={send} className="border-t border-slate-100 p-4"><textarea value={reply} onChange={(e) => setReply(e.target.value)} placeholder="Write a reply..." className="min-h-20 w-full resize-none rounded-lg border border-slate-200 bg-slate-50 p-3 text-sm outline-none focus:border-indigo-400" /><div className="mt-3 flex items-center gap-2"><button type="button" onClick={() => notify('Attachment picker opened')} className="rounded-lg border border-slate-200 px-3 py-2 text-xs text-slate-500">Attach file</button><button type="button" onClick={() => setReply('Hi there, thanks for reaching out. I am looking into this and will follow up shortly.')} className="rounded-lg border border-slate-200 px-3 py-2 text-xs text-slate-500">Use template</button><button className="ml-auto rounded-lg bg-indigo-600 px-4 py-2 text-xs font-semibold text-white">Send reply</button></div></form></section><aside className="border-t border-slate-200 p-5 lg:border-l lg:border-t-0"><p className="text-[10px] font-semibold uppercase tracking-wider text-slate-400">Customer details</p><div className="mt-4 flex items-center gap-3"><div className="flex size-10 items-center justify-center rounded-full bg-rose-100 text-sm font-bold text-rose-700">{initials(selected.customer)}</div><div><p className="text-sm font-semibold">{selected.customer}</p><p className="text-xs text-slate-400">{selected.company}</p></div></div><div className="mt-6 flex flex-col gap-3 text-xs"><div><p className="text-slate-400">Status</p><p className="mt-1 font-medium">{selected.status}</p></div><div><p className="text-slate-400">Priority</p><p className="mt-1 font-medium">{selected.priority}</p></div><div><p className="text-slate-400">Assigned to</p><p className="mt-1 font-medium">Ahmed Raza</p></div></div><div className="mt-6 border-t border-slate-100 pt-4"><p className="text-xs font-semibold">Related records</p><button onClick={() => notify('Contact profile opened')} className="mt-3 w-full rounded-lg border border-slate-200 px-3 py-2 text-left text-xs font-medium hover:border-indigo-300">Open contact profile <ChevronRight className="float-right size-3.5 text-slate-400" /></button><button onClick={() => notify('Deal opened')} className="mt-2 w-full rounded-lg border border-slate-200 px-3 py-2 text-left text-xs font-medium hover:border-indigo-300">Enterprise expansion <ChevronRight className="float-right size-3.5 text-slate-400" /></button></div></aside></div></div>
}

function SupportView({ notify }: { notify: (v: string) => void }) {
  const [tickets, setTickets] = useState(ticketSeed)
  const [selectedId, setSelectedId] = useState('SUP-1048')
  const [status, setStatus] = useState<'All' | SupportTicket['status']>('All')
  const [priority, setPriority] = useState('All')
  const [showCreate, setShowCreate] = useState(false)
  const [note, setNote] = useState('')
  const selected = tickets.find((ticket) => ticket.id === selectedId) || tickets[0]
  const visible = tickets.filter((ticket) => (status === 'All' || ticket.status === status) && (priority === 'All' || ticket.priority === priority))
  const addNote = (event: React.FormEvent) => { event.preventDefault(); if (!note.trim()) return; setTickets((current) => current.map((ticket) => ticket.id === selected.id ? { ...ticket, messages: [...ticket.messages, { from: 'Ahmed Raza', text: note.trim(), time: 'Just now', internal: true }] } : ticket)); setNote(''); notify('Internal note added') }
  return <div className="p-5 lg:p-8"><PageHeader eyebrow="Engage" title="Support tickets" description="Resolve customer issues with clarity and speed" action="Create ticket" onAction={() => setShowCreate(true)} /><div className="mb-5 grid gap-3 sm:grid-cols-3">{[['Open tickets', tickets.filter((t) => t.status === 'Open').length, 'Needs attention'], ['SLA at risk', '2', 'Next 2 hours'], ['CSAT', '4.8 / 5', '+0.3 this month']].map(([label, value, sub]) => <div key={String(label)} className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs text-slate-500">{String(label)}</p><p className="mt-2 text-2xl font-semibold">{value}</p><p className="mt-1 text-[11px] text-slate-400">{String(sub)}</p></div>)}</div><div className="grid overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm lg:grid-cols-[360px_minmax(0,1fr)]"><section className="border-b border-slate-200 lg:border-b-0 lg:border-r"><div className="flex flex-wrap gap-2 border-b border-slate-100 p-4"><select value={status} onChange={(e) => setStatus(e.target.value as typeof status)} className="h-9 rounded-lg border border-slate-200 px-2 text-xs"><option>All</option><option>Open</option><option>Pending</option><option>Resolved</option></select><select value={priority} onChange={(e) => setPriority(e.target.value)} className="h-9 rounded-lg border border-slate-200 px-2 text-xs"><option>All</option><option>Urgent</option><option>High</option><option>Normal</option></select><button onClick={() => notify('Ticket filters applied')} className="ml-auto rounded-lg border border-slate-200 px-3 text-xs text-slate-500"><Filter className="inline size-3.5" /></button></div><div className="divide-y divide-slate-100">{visible.map((ticket) => <button key={ticket.id} onClick={() => setSelectedId(ticket.id)} className={`w-full p-4 text-left hover:bg-slate-50 ${selected.id === ticket.id ? 'bg-indigo-50/60' : ''}`}><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="text-[10px] font-semibold text-slate-400">{ticket.id}</p><p className="mt-1 truncate text-sm font-semibold">{ticket.subject}</p><p className="mt-1 text-xs text-slate-500">{ticket.customer} · {ticket.company}</p></div><span className={`rounded-full px-2 py-1 text-[10px] font-semibold ${ticket.priority === 'Urgent' ? 'bg-rose-50 text-rose-600' : 'bg-slate-100 text-slate-500'}`}>{ticket.priority}</span></div><div className="mt-3 flex items-center justify-between text-[10px] text-slate-400"><span>{ticket.status}</span><span className={ticket.sla.includes('left') ? 'font-semibold text-amber-600' : ''}>{ticket.sla}</span></div></button>)}</div></section><section className="flex min-h-[600px] flex-col"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 p-5"><div><p className="text-xs font-semibold text-slate-400">{selected.id}</p><h2 className="mt-1 text-lg font-semibold">{selected.subject}</h2><p className="mt-1 text-xs text-slate-500">{selected.customer} · {selected.company} · Created {selected.created}</p></div><div className="flex items-center gap-2"><select value={selected.status} onChange={(e) => { const next = e.target.value as SupportTicket['status']; setTickets((current) => current.map((ticket) => ticket.id === selected.id ? { ...ticket, status: next, sla: next === 'Resolved' ? 'Resolved' : ticket.sla } : ticket)); notify(`Ticket marked ${next.toLowerCase()}`) }} className="h-9 rounded-lg border border-slate-200 px-2 text-xs"><option>Open</option><option>Pending</option><option>Resolved</option></select><button onClick={() => notify('Ticket assignment opened')} className="rounded-lg border border-slate-200 px-3 py-2 text-xs font-medium">Assign</button></div></div><div className="flex-1 space-y-4 bg-slate-50/60 p-5">{selected.messages.map((message, index) => <div key={`${message.time}-${index}`} className={`flex ${message.internal ? 'justify-center' : 'justify-start'}`}><div className={`max-w-[75%] rounded-2xl px-4 py-3 text-sm ${message.internal ? 'bg-amber-50 text-amber-800' : 'border border-slate-200 bg-white text-slate-700'}`}><p className="text-[10px] font-semibold opacity-70">{message.internal ? 'Internal note · ' : ''}{message.from}</p><p className="mt-1 leading-6">{message.text}</p><p className="mt-2 text-[10px] opacity-60">{message.time}</p></div></div>)}</div><form onSubmit={addNote} className="border-t border-slate-100 p-4"><div className="flex gap-2"><input value={note} onChange={(e) => setNote(e.target.value)} placeholder="Add an internal note" className="h-10 flex-1 rounded-lg border border-slate-200 bg-slate-50 px-3 text-sm outline-none focus:border-indigo-400" /><button className="rounded-lg bg-indigo-600 px-4 text-xs font-semibold text-white">Add note</button></div><div className="mt-3 flex items-center justify-between text-xs text-slate-400"><span>Assigned agent: <strong className="text-slate-600">{selected.agent}</strong></span><span>{selected.satisfaction ? `CSAT ${selected.satisfaction}/5` : 'Awaiting satisfaction rating'}</span></div></form></section></div>{showCreate && <Modal title="Create support ticket" onClose={() => setShowCreate(false)}><form onSubmit={(event) => { event.preventDefault(); setShowCreate(false); notify('Support ticket created') }} className="flex flex-col gap-4"><label className="text-xs font-medium">Subject<input required name="subject" className="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm" placeholder="What does the customer need help with?" /></label><label className="text-xs font-medium">Customer<input required name="customer" className="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm" placeholder="Customer name" /></label><label className="text-xs font-medium">Priority<select className="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm"><option>Normal</option><option>High</option><option>Urgent</option></select></label><div className="flex justify-end gap-2"><button type="button" onClick={() => setShowCreate(false)} className="rounded-lg px-3 py-2 text-sm text-slate-500">Cancel</button><button className="rounded-lg bg-indigo-600 px-3 py-2 text-sm font-semibold text-white">Create ticket</button></div></form></Modal>}</div>
}

function AutomationView({ notify }: { notify: (v: string) => void }) {
  const [workflows, setWorkflows] = useState(workflowSeed)
  const [selectedId, setSelectedId] = useState('wf-1')
  const [query, setQuery] = useState('')
  const [status, setStatus] = useState<'All' | WorkflowStatus>('All')
  const [editor, setEditor] = useState(false)
  const [activeTab, setActiveTab] = useState<'Canvas' | 'Runs'>('Canvas')
  const [selectedNode, setSelectedNode] = useState<string | null>(null)
  const [zoom, setZoom] = useState(100)
  const [dirty, setDirty] = useState(false)
  const [showAdd, setShowAdd] = useState(false)
  const current = workflows.find((workflow) => workflow.id === selectedId) || workflows[0]
  const visible = workflows.filter((workflow) => (status === 'All' || workflow.status === status) && `${workflow.name} ${workflow.description} ${workflow.category}`.toLowerCase().includes(query.toLowerCase()))
  const updateWorkflow = (patch: Partial<Workflow>) => { setWorkflows((items) => items.map((item) => item.id === current.id ? { ...item, ...patch } : item)); setDirty(true) }
  const addNode = (type: WorkflowNode['type'], title: string, subtitle: string, color: string) => { const node: WorkflowNode = { id: `node-${Date.now()}`, type, title, subtitle, x: 110, y: 430 + current.nodes.length * 12, color }; updateWorkflow({ nodes: [...current.nodes, node] }); setShowAdd(false); notify(`${title} added to workflow`) }
  const removeNode = (id: string) => { updateWorkflow({ nodes: current.nodes.filter((node) => node.id !== id) }); setSelectedNode(null); notify('Node deleted') }
  const [showCreate, setShowCreate] = useState(false)
  const [newName, setNewName] = useState('')
  if (editor) return <div className="p-5 lg:p-8"><div className="mb-5 flex flex-wrap items-center gap-3"><button onClick={() => setEditor(false)} className="flex items-center gap-2 text-xs font-medium text-slate-500 hover:text-slate-900"><ChevronLeft className="size-4" />All workflows</button><span className="text-slate-300">/</span><span className="text-sm font-semibold">{current.name}</span>{dirty && <span className="rounded-full bg-amber-50 px-2 py-1 text-[10px] font-semibold text-amber-700">Unsaved changes</span>}<div className="ml-auto flex gap-2"><button onClick={() => { setDirty(false); notify('Workflow saved') }} className={smallButton}>Save draft</button><button onClick={() => { updateWorkflow({ status: 'Active' }); setDirty(false); notify('Workflow published') }} className="rounded-lg bg-indigo-600 px-3 py-2 text-xs font-semibold text-white">Publish</button><button onClick={() => { updateWorkflow({ status: current.status === 'Paused' ? 'Active' : 'Paused' }); notify(current.status === 'Paused' ? 'Workflow resumed' : 'Workflow paused') }} className={smallButton}>{current.status === 'Paused' ? 'Resume' : 'Pause'}</button></div></div><div className="mb-5 flex items-center justify-between"><div><p className="text-xs font-medium text-indigo-600">Automation builder</p><h1 className="text-2xl font-semibold tracking-tight">{current.name}</h1><p className="mt-1 max-w-xl text-sm text-slate-500">{current.description}</p></div><div className="flex rounded-lg border border-slate-200 bg-white p-1"><button onClick={() => setActiveTab('Canvas')} className={`rounded-md px-3 py-1.5 text-xs font-medium ${activeTab === 'Canvas' ? 'bg-slate-100' : 'text-slate-500'}`}>Canvas</button><button onClick={() => setActiveTab('Runs')} className={`rounded-md px-3 py-1.5 text-xs font-medium ${activeTab === 'Runs' ? 'bg-slate-100' : 'text-slate-500'}`}>Run history</button></div></div>{activeTab === 'Runs' ? <div className="rounded-xl border border-slate-200 bg-white shadow-sm"><div className="border-b border-slate-100 p-4"><h2 className="text-sm font-semibold">Simulated execution logs</h2><p className="mt-1 text-xs text-slate-500">Frontend-only activity for this workflow.</p></div>{current.runs ? ['Contact created · Olivia Rhye', 'Create task · Welcome sequence', 'Notification sent · Account owner'].map((row, index) => <div key={row} className="flex items-center gap-3 border-b border-slate-100 px-5 py-4 text-xs"><span className="flex size-6 items-center justify-center rounded-full bg-emerald-50 text-emerald-600"><Check className="size-3.5" /></span><span className="flex-1">{row}</span><span className="text-slate-400">{index + 1} hour{index ? 's' : ''} ago</span></div>) : <div className="p-12 text-center text-sm text-slate-400">No executions yet</div>}</div> : <div className="grid gap-4 xl:grid-cols-[minmax(0,1fr)_300px]"><div className="relative min-h-[610px] overflow-hidden rounded-xl border border-slate-200 bg-slate-50 shadow-sm"><div className="absolute inset-0 opacity-60" style={{ backgroundImage: 'radial-gradient(#cbd5e1 1px, transparent 1px)', backgroundSize: '20px 20px' }} /><div className="absolute right-4 top-4 z-10 flex items-center gap-1 rounded-lg border border-slate-200 bg-white p-1 shadow-sm"><button onClick={() => setZoom((value) => Math.max(60, value - 10))} className="flex size-7 items-center justify-center text-slate-500">−</button><span className="w-10 text-center text-[10px] font-semibold">{zoom}%</span><button onClick={() => setZoom((value) => Math.min(140, value + 10))} className="flex size-7 items-center justify-center text-slate-500">+</button></div><div className="absolute bottom-4 right-4 z-10 rounded-lg border border-slate-200 bg-white p-2 shadow-sm"><div className="mb-1 text-[9px] font-semibold uppercase tracking-wider text-slate-400">Minimap</div><div className="h-16 w-24 rounded bg-slate-100 p-1">{current.nodes.map((node) => <span key={node.id} className="mb-1 block h-1 rounded bg-indigo-300" />)}</div></div><div className="relative z-[1] mx-auto flex w-[340px] flex-col items-center gap-0 pt-14" style={{ transform: `scale(${zoom / 100})`, transformOrigin: 'top center' }}>{current.nodes.map((node, index) => <div key={node.id} className="flex w-full flex-col items-center"><div className={`relative w-[250px] cursor-pointer rounded-xl border-2 bg-white p-3 text-left shadow-sm transition ${selectedNode === node.id ? 'border-indigo-500 shadow-indigo-100' : 'border-slate-200 hover:border-indigo-300'}`} onClick={() => setSelectedNode(node.id)}><div className="flex items-start gap-3"><div className={`flex size-8 shrink-0 items-center justify-center rounded-lg ${node.color === 'indigo' ? 'bg-indigo-50 text-indigo-600' : node.color === 'emerald' ? 'bg-emerald-50 text-emerald-600' : node.color === 'amber' ? 'bg-amber-50 text-amber-600' : node.color === 'violet' ? 'bg-violet-50 text-violet-600' : 'bg-sky-50 text-sky-600'}`}>{node.type === 'trigger' ? <Zap className="size-4" /> : node.type === 'condition' ? <SlidersHorizontal className="size-4" /> : <Check className="size-4" />}</div><div className="min-w-0"><p className="text-xs font-semibold">{node.title}</p><p className="mt-1 text-[10px] leading-4 text-slate-500">{node.subtitle}</p></div><button onClick={(event) => { event.stopPropagation(); removeNode(node.id) }} className="ml-auto text-slate-300 hover:text-rose-500"><X className="size-3.5" /></button></div></div>{index < current.nodes.length - 1 && <div className="h-12 w-px border-l-2 border-dashed border-slate-300" />}</div>)}<button onClick={() => setShowAdd(true)} className="mt-4 flex items-center gap-2 rounded-lg border border-dashed border-indigo-300 bg-white px-4 py-2 text-xs font-semibold text-indigo-600 hover:bg-indigo-50"><Plus className="size-3.5" />Add node</button></div></div><aside className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs font-semibold">{selectedNode ? 'Node configuration' : 'Workflow settings'}</p>{selectedNode ? <div className="mt-4 flex flex-col gap-4"><label className="text-xs font-medium">Node label<input value={current.nodes.find((node) => node.id === selectedNode)?.title || ''} onChange={(event) => updateWorkflow({ nodes: current.nodes.map((node) => node.id === selectedNode ? { ...node, title: event.target.value } : node) })} className="mt-1.5 h-9 w-full rounded-lg border border-slate-200 px-3 text-sm outline-none focus:border-indigo-500" /></label><label className="text-xs font-medium">Description<textarea value={current.nodes.find((node) => node.id === selectedNode)?.subtitle || ''} onChange={(event) => updateWorkflow({ nodes: current.nodes.map((node) => node.id === selectedNode ? { ...node, subtitle: event.target.value } : node) })} className="mt-1.5 min-h-20 w-full rounded-lg border border-slate-200 p-3 text-sm outline-none focus:border-indigo-500" /></label><button onClick={() => removeNode(selectedNode)} className="rounded-lg border border-rose-200 px-3 py-2 text-xs font-semibold text-rose-600">Delete node</button></div> : <div className="mt-4 flex flex-col gap-4"><label className="text-xs font-medium">Workflow name<input value={current.name} onChange={(event) => updateWorkflow({ name: event.target.value })} className="mt-1.5 h-9 w-full rounded-lg border border-slate-200 px-3 text-sm outline-none focus:border-indigo-500" /></label><label className="text-xs font-medium">Category<select value={current.category} onChange={(event) => updateWorkflow({ category: event.target.value })} className="mt-1.5 h-9 w-full rounded-lg border border-slate-200 bg-white px-3 text-sm"><option>Lifecycle</option><option>Sales</option><option>Productivity</option><option>Marketing</option></select></label><div className="rounded-lg bg-slate-50 p-3 text-xs text-slate-500">This workflow is a UI prototype. Publishing does not execute real automations.</div></div>}</aside></div>}{showAdd && <Modal title="Add workflow node" onClose={() => setShowAdd(false)}><div className="grid gap-2">{[['trigger', 'Contact created', 'Starts when a contact is created', 'indigo'], ['trigger', 'Deal stage changed', 'Starts when a deal changes stage', 'indigo'], ['action', 'Create task', 'Create a follow-up task', 'emerald'], ['action', 'Assign owner', 'Assign a teammate', 'sky'], ['action', 'Add tag', 'Add a CRM tag', 'rose'], ['action', 'Create notification', 'Notify the team', 'amber'], ['condition', 'Check condition', 'Branch based on record data', 'violet']].map(([type, title, subtitle, color]) => <button key={`${type}-${title}`} onClick={() => addNode(type as WorkflowNode['type'], title, subtitle, color)} className="flex items-center gap-3 rounded-lg border border-slate-200 p-3 text-left hover:border-indigo-300 hover:bg-indigo-50"><span className="flex size-8 items-center justify-center rounded-lg bg-slate-100 text-indigo-600"><Plus className="size-4" /></span><span><span className="block text-xs font-semibold">{title}</span><span className="block text-[10px] text-slate-500">{subtitle}</span></span></button>)}</div></Modal>}</div>
  const create = () => { if (!newName.trim()) { notify('Enter a workflow name'); return } const id = `wf-${Date.now()}`; const workflow: Workflow = { id, name: newName.trim(), description: 'New workflow ready to configure.', status: 'Draft', category: 'Lifecycle', owner: 'Ahmed Raza', edited: 'Just now', runs: 0, nodes: [{ id: 'n1', type: 'trigger', title: 'Choose a trigger', subtitle: 'Start your workflow', x: 110, y: 80, color: 'indigo' }] }; setWorkflows((items) => [workflow, ...items]); setSelectedId(id); setNewName(''); setShowCreate(false); setEditor(true); notify('Workflow created') }
  return <div className="p-5 lg:p-8"><PageHeader eyebrow="Analyze" title="Workflow automation" description="Build repeatable processes that keep your team moving" action="Create workflow" onAction={() => setShowCreate(true)} /><div className="mb-6 grid gap-3 sm:grid-cols-3">{[['Active workflows', workflows.filter((item) => item.status === 'Active').length, 'Running automatically'], ['Executions this month', '2,222', '+18.4% vs last month'], ['Time saved', '46.5h', 'Estimated this month']].map(([label, value, sub]) => <div key={String(label)} className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs text-slate-500">{label}</p><p className="mt-2 text-2xl font-semibold">{value}</p><p className="mt-1 text-[11px] text-slate-400">{sub}</p></div>)}</div><div className="mb-4 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-2.5 size-4 text-slate-400" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search workflows..." className="h-9 w-full rounded-lg border border-slate-200 bg-white pl-9 pr-3 text-sm outline-none focus:border-indigo-400" /></div><select value={status} onChange={(event) => setStatus(event.target.value as typeof status)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-xs"><option>All</option><option>Active</option><option>Draft</option><option>Paused</option></select><button onClick={() => notify('Workflow categories opened')} className={smallButton}><Filter className="size-3.5" />Categories</button></div><div className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><div className="overflow-x-auto"><table className="w-full min-w-[880px] text-left text-sm"><thead className="bg-slate-50 text-[10px] uppercase tracking-wider text-slate-400"><tr><th className="px-5 py-3">Workflow</th><th className="px-3 py-3">Status</th><th className="px-3 py-3">Category</th><th className="px-3 py-3">Owner</th><th className="px-3 py-3">Last edited</th><th className="px-3 py-3 text-right">Executions</th><th className="px-3 py-3" /></tr></thead><tbody>{visible.map((workflow) => <tr key={workflow.id} className="border-t border-slate-100"><td className="px-5 py-4"><button onClick={() => { setSelectedId(workflow.id); setEditor(true) }} className="flex items-center gap-3 text-left"><span className="flex size-9 items-center justify-center rounded-lg bg-indigo-50 text-indigo-600"><Zap className="size-4" /></span><span><span className="block font-medium hover:text-indigo-600">{workflow.name}</span><span className="block max-w-[340px] truncate text-xs text-slate-400">{workflow.description}</span></span></button></td><td className="px-3 py-4"><span className={`rounded-full px-2 py-1 text-[10px] font-semibold ${workflow.status === 'Active' ? 'bg-emerald-50 text-emerald-700' : workflow.status === 'Paused' ? 'bg-amber-50 text-amber-700' : 'bg-slate-100 text-slate-600'}`}>{workflow.status}</span></td><td className="px-3 py-4 text-slate-600">{workflow.category}</td><td className="px-3 py-4 text-slate-600">{workflow.owner}</td><td className="px-3 py-4 text-slate-500">{workflow.edited}</td><td className="px-3 py-4 text-right font-semibold">{workflow.runs.toLocaleString()}</td><td className="px-3 py-4"><button onClick={() => { setSelectedId(workflow.id); setEditor(true) }} className="rounded-md p-2 text-slate-400 hover:bg-slate-50"><ChevronRight className="size-4" /></button></td></tr>)}</tbody></table>{visible.length === 0 && <div className="p-12 text-center text-sm text-slate-400">No workflows match your filters.</div>}</div></div>{showCreate && <Modal title="Create workflow" onClose={() => setShowCreate(false)}><div className="flex flex-col gap-4"><label className="text-xs font-medium">Workflow name<input autoFocus value={newName} onChange={(event) => setNewName(event.target.value)} placeholder="e.g. New customer handoff" className="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm outline-none focus:border-indigo-500" /></label><p className="text-xs text-slate-500">Start with a blank workflow and configure the trigger and actions in the visual editor.</p><div className="flex justify-end gap-2"><button onClick={() => setShowCreate(false)} className="rounded-lg px-3 py-2 text-sm font-medium text-slate-500">Cancel</button><button onClick={create} className="rounded-lg bg-indigo-600 px-3 py-2 text-sm font-semibold text-white">Create workflow</button></div></div></Modal>}</div>
}

function GenericView({ view, notify }: { view: View; notify: (v: string) => void }) {
  const config: Record<string, { title: string; desc: string; action: string; Icon: typeof Users }> = {
    Companies: { title: 'Companies', desc: 'Track accounts, relationships, and growth opportunities', action: 'Add company', Icon: Building2 },
    Inbox: { title: 'Communication inbox', desc: 'Keep every customer conversation moving forward', action: 'New conversation', Icon: Inbox },
    Reports: { title: 'Reports & analytics', desc: 'Understand performance across your entire revenue engine', action: 'Create report', Icon: TrendingUp },
  }
  const item = config[view] || { title: view, desc: 'Manage your workspace with clarity and confidence', action: 'Create new', Icon: Users }
  const metrics = [['Active records', '1,284', '+12.4%'], ['This month', '$84.6k', '+18.2%'], ['Needs attention', '18', 'View queue']]
  return <div className="p-5 lg:p-8"><PageHeader eyebrow="Workspace" title={item.title} description={item.desc} action={item.action} onAction={() => notify(`${item.action} flow opened`)} /><div className="grid gap-4 md:grid-cols-3">{metrics.map(([label, value, change]) => <div key={String(label)} className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><span className="text-xs text-slate-500">{String(label)}</span><TrendingUp className="size-4 text-indigo-500" /></div><p className="mt-4 text-2xl font-semibold">{value}</p><p className="mt-1 text-xs text-emerald-600">{String(change)}</p></div>)}</div><div className="mt-6 rounded-xl border border-slate-200 bg-white p-12 text-center shadow-sm"><div className="mx-auto flex size-12 items-center justify-center rounded-2xl bg-indigo-50 text-indigo-600"><item.Icon className="size-5" /></div><h2 className="mt-4 text-base font-semibold">Your {item.title.toLowerCase()} workspace</h2><p className="mx-auto mt-2 max-w-md text-sm text-slate-500">This module is ready for your team. Use the action above to start building your workspace, or connect it to your existing process.</p><button onClick={() => notify(`${item.action} flow opened`)} className="mt-5 rounded-lg bg-indigo-600 px-4 py-2 text-xs font-semibold text-white">{item.action}</button></div></div>
}
function Modal({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) { return <div className="fixed inset-0 z-40 flex items-center justify-center bg-slate-950/40 p-4 backdrop-blur-sm"><div className="w-full max-w-md rounded-2xl border border-slate-200 bg-white p-5 shadow-2xl dark:border-slate-700 dark:bg-slate-900"><div className="mb-5 flex items-center justify-between"><h2 className="text-base font-semibold">{title}</h2><button onClick={onClose} className="rounded-md p-1 text-slate-400 hover:bg-slate-100"><X className="size-4" /></button></div>{children}</div></div> }
function QuickCreate({ onClose, onAction }: { onClose: () => void; onAction: (v: string) => void }) { return <Modal title="Quick create" onClose={onClose}><div className="grid grid-cols-2 gap-2">{[['Contact', ContactRound], ['Company', Building2], ['Deal', BriefcaseBusiness], ['Task', Check], ['Note', Mail], ['Event', CalendarDays]].map(([label, Icon]) => { const QuickIcon = Icon as React.ElementType; return <button key={String(label)} onClick={() => onAction(String(label))} className="flex items-center gap-3 rounded-xl border border-slate-200 p-3 text-left text-sm font-medium hover:border-indigo-300 hover:bg-indigo-50"><QuickIcon className="size-4 text-indigo-600" />{String(label)}</button>})}</div></Modal> }
function ContactDialog({ onClose, onSubmit }: { onClose: () => void; onSubmit: (event: React.FormEvent<HTMLFormElement>) => void }) { return <Modal title="Add contact" onClose={onClose}><form onSubmit={onSubmit} className="flex flex-col gap-4"><label className="text-xs font-medium">Full name<input name="name" required placeholder="e.g. Jordan Lee" className="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm outline-none focus:border-indigo-500" /></label><label className="text-xs font-medium">Email<input name="email" type="email" required placeholder="jordan@company.com" className="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm outline-none focus:border-indigo-500" /></label><label className="text-xs font-medium">Company<input name="company" placeholder="Company name" className="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm outline-none focus:border-indigo-500" /></label><div className="flex justify-end gap-2 pt-2"><button type="button" onClick={onClose} className="rounded-lg px-3 py-2 text-sm font-medium text-slate-500">Cancel</button><button className="rounded-lg bg-indigo-600 px-3 py-2 text-sm font-semibold text-white">Add contact</button></div></form></Modal> }
function SearchDialog({ query, setQuery, onClose, onSelect }: { query: string; setQuery: (v: string) => void; onClose: () => void; onSelect: (v: string) => void }) { const results = [...contacts.map((c) => ({ label: c.name, meta: c.company, view: 'Contacts' })), ...companies.map((c) => ({ label: c.name, meta: c.industry, view: 'Companies' })), ...leads.map((l) => ({ label: l.name, meta: l.company, view: 'Leads' })), ...deals.map((d) => ({ label: d.name, meta: d.company, view: 'Deals' }))].filter((item) => `${item.label} ${item.meta}`.toLowerCase().includes(query.toLowerCase())).slice(0, 8); return <Modal title="Search workspace" onClose={onClose}><div className="relative"><Search className="absolute left-3 top-3 size-4 text-slate-400" /><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search contacts, companies, leads..." className="h-10 w-full rounded-lg border border-slate-200 bg-slate-50 pl-9 pr-3 text-sm outline-none focus:border-indigo-500" /></div><div className="mt-3 flex flex-col gap-1">{results.map((item) => <button key={`${item.view}-${item.label}`} onClick={() => onSelect(item.view)} className="flex items-center gap-3 rounded-lg p-2.5 text-left hover:bg-slate-50"><div className="flex size-7 items-center justify-center rounded-md bg-indigo-50 text-indigo-600"><Search className="size-3.5" /></div><div><p className="text-sm font-medium">{item.label}</p><p className="text-xs text-slate-400">{item.meta}</p></div><ChevronRight className="ml-auto size-3.5 text-slate-300" /></button>)}{query && results.length === 0 && <p className="p-5 text-center text-sm text-slate-400">No results found.</p>}</div></Modal> }

function CompaniesView({ companies, query, setQuery, notify, onOpen }: { companies: Company[]; query: string; setQuery: (v: string) => void; notify: (v: string) => void; onOpen: (id: string) => void }) { const rows = companies.filter((company) => `${company.name} ${company.industry} ${company.location}`.toLowerCase().includes(query.toLowerCase())); return <div className="p-5 lg:p-8"><PageHeader eyebrow="Manage" title="Companies" description={`${companies.length} accounts with active relationships`} action="Add company" onAction={() => notify('Company form opened')} /><div className={tableShell}><Toolbar query={query} setQuery={setQuery} placeholder="Search companies, industries, locations..." notify={notify} /><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left text-sm"><thead className="bg-slate-50 text-[10px] uppercase tracking-wider text-slate-400 dark:bg-slate-800/50"><tr><th className="px-5 py-3">Company</th><th className="px-3 py-3">Industry</th><th className="px-3 py-3">Size</th><th className="px-3 py-3">Location</th><th className="px-3 py-3">Revenue</th><th className="px-3 py-3">Owner</th><th className="px-3 py-3">Relations</th></tr></thead><tbody>{rows.map((company) => <tr key={company.id} className="border-t border-slate-100 dark:border-slate-800"><td className="px-5 py-4"><button onClick={() => onOpen(company.id)} className="flex items-center gap-3 text-left"><span className="flex size-8 items-center justify-center rounded-lg bg-indigo-50 text-indigo-600"><Building2 className="size-4" /></span><span><span className="block font-medium hover:text-indigo-600">{company.name}</span><span className="block text-xs text-slate-400">{company.website}</span></span></button></td><td className="px-3 py-4 text-slate-600">{company.industry}</td><td className="px-3 py-4 text-slate-600">{company.size}</td><td className="px-3 py-4 text-slate-600">{company.location}</td><td className="px-3 py-4 font-medium">{company.revenue}</td><td className="px-3 py-4 text-xs font-semibold">{company.owner}</td><td className="px-3 py-4 text-xs text-slate-500">{company.contacts} contacts · {company.deals} deals</td></tr>)}</tbody></table></div></div></div> }
function LeadsView({ leads, setLeads, notify, onOpen }: { leads: Lead[]; setLeads: React.Dispatch<React.SetStateAction<Lead[]>>; notify: (v: string) => void; onOpen: (id: string) => void }) { const [query, setQuery] = useState(''); const rows = leads.filter((lead) => `${lead.name} ${lead.email} ${lead.company} ${lead.status}`.toLowerCase().includes(query.toLowerCase())); const convert = (lead: Lead) => { setLeads((current) => current.map((item) => item.id === lead.id ? { ...item, status: 'Converted' } : item)); notify(`${lead.name} converted into a contact and deal`) }; return <div className="p-5 lg:p-8"><PageHeader eyebrow="Manage" title="Leads" description="Qualify demand and turn the right conversations into pipeline" action="Add lead" onAction={() => notify('Lead form opened')} /><div className={tableShell}><Toolbar query={query} setQuery={setQuery} placeholder="Search leads, companies, status..." notify={notify} /><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left text-sm"><thead className="bg-slate-50 text-[10px] uppercase tracking-wider text-slate-400 dark:bg-slate-800/50"><tr><th className="px-5 py-3">Lead</th><th className="px-3 py-3">Source</th><th className="px-3 py-3">Score</th><th className="px-3 py-3">Status</th><th className="px-3 py-3">Owner</th><th className="px-3 py-3">Contact</th><th className="px-3 py-3" /></tr></thead><tbody>{rows.map((lead) => <tr key={lead.id} className="border-t border-slate-100 dark:border-slate-800"><td className="px-5 py-4"><button onClick={() => onOpen(lead.id)} className="text-left"><span className="block font-medium hover:text-indigo-600">{lead.name}</span><span className="block text-xs text-slate-400">{lead.company} · {lead.email}</span></button></td><td className="px-3 py-4 text-slate-600">{lead.source}</td><td className="px-3 py-4"><span className={`font-semibold ${lead.score > 80 ? 'text-emerald-600' : lead.score > 60 ? 'text-amber-600' : 'text-slate-500'}`}>{lead.score}/100</span></td><td className="px-3 py-4"><span className="rounded-full bg-indigo-50 px-2 py-1 text-[11px] font-medium text-indigo-700">{lead.status}</span></td><td className="px-3 py-4 text-xs font-semibold">{lead.owner}</td><td className="px-3 py-4 text-xs text-slate-500">{lead.phone}</td><td className="px-3 py-4 text-right">{lead.status !== 'Converted' && <button onClick={() => convert(lead)} className="rounded-lg bg-indigo-600 px-2.5 py-1.5 text-[11px] font-semibold text-white">Convert</button>}</td></tr>)}</tbody></table></div></div></div> }
function RecordDetail({ record, type, onClose, onNotify }: { record?: Contact | Company | Lead; type: 'contact' | 'company' | 'lead'; onClose: () => void; onNotify: (v: string) => void }) { if (!record) return null; const name = 'name' in record ? record.name : ''; return <Modal title={type === 'contact' ? 'Contact profile' : type === 'company' ? 'Company profile' : 'Lead details'} onClose={onClose}><div className="flex items-center gap-3 border-b border-slate-100 pb-4"><div className="flex size-12 items-center justify-center rounded-xl bg-indigo-50 text-indigo-700"><UserRound className="size-5" /></div><div><h3 className="font-semibold">{name}</h3><p className="text-xs text-slate-400">{type === 'contact' ? (record as Contact).email : type === 'company' ? (record as Company).website : (record as Lead).email}</p></div></div><div className="mt-4 grid grid-cols-2 gap-3 text-xs"><div className="rounded-lg bg-slate-50 p-3"><p className="text-slate-400">Owner</p><p className="mt-1 font-semibold">{'owner' in record ? record.owner : 'AR'}</p></div><div className="rounded-lg bg-slate-50 p-3"><p className="text-slate-400">Activity</p><p className="mt-1 font-semibold">Today, 10:42 AM</p></div></div><div className="mt-5 flex gap-2"><button onClick={() => onNotify('Note added')} className={smallButton}><Mail className="size-3.5" />Add note</button><button onClick={() => onNotify('Task created')} className={smallButton}><Check className="size-3.5" />Create task</button></div><div className="mt-5 border-t border-slate-100 pt-4"><p className="mb-3 text-xs font-semibold uppercase tracking-wider text-slate-400">Recent activity</p><div className="flex flex-col gap-3 text-xs text-slate-500"><p><span className="mr-2 inline-block size-2 rounded-full bg-indigo-500" />Profile viewed · Today</p><p><span className="mr-2 inline-block size-2 rounded-full bg-emerald-500" />Email sent �� Yesterday</p><p><span className="mr-2 inline-block size-2 rounded-full bg-amber-500" />Task completed · Oct 22</p></div></div></Modal> }

function CampaignsView({ campaigns, setCampaigns, notify }: { campaigns: Campaign[]; setCampaigns: React.Dispatch<React.SetStateAction<Campaign[]>>; notify: (v: string) => void }) {
  const [query, setQuery] = useState(''); const [status, setStatus] = useState<'All' | CampaignStatus>('All'); const [step, setStep] = useState(0); const [wizard, setWizard] = useState(false); const [draft, setDraft] = useState({ name: '', subject: '', audience: 'Active customers', sender: 'Ahmed Raza' });
  const visible = campaigns.filter((c) => (status === 'All' || c.status === status) && `${c.name} ${c.subject} ${c.audience}`.toLowerCase().includes(query.toLowerCase()));
  const openWizard = () => { setDraft({ name: '', subject: '', audience: 'Active customers', sender: 'Ahmed Raza' }); setStep(0); setWizard(true) };
  const saveDraft = () => { if (!draft.name.trim() || !draft.subject.trim()) { notify('Add a campaign name and subject first'); return } setCampaigns((current) => [{ id: `cmp-${Date.now()}`, name: draft.name, subject: draft.subject, status: 'Draft', audience: draft.audience, sent: 'Not scheduled', opens: 0, clicks: 0, delivered: 0, bounces: 0, unsubscribes: 0, conversions: 0, sender: draft.sender }, ...current]); setWizard(false); notify('Campaign saved as draft') };
  const changeStatus = (campaign: Campaign) => { const next: CampaignStatus = campaign.status === 'Paused' ? 'Scheduled' : campaign.status === 'Scheduled' ? 'Paused' : 'Paused'; setCampaigns((current) => current.map((item) => item.id === campaign.id ? { ...item, status: next } : item)); notify(`${campaign.name} is now ${next.toLowerCase()}`) };
  return <div className="p-5 lg:p-8"><PageHeader eyebrow="Engage" title="Email campaigns" description="Create targeted campaigns and learn what moves your audience" action="Create campaign" onAction={openWizard} /><div className="mb-6 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[['Total delivered','98.9%','+1.8%'],['Average open rate','47.2%','+6.4%'],['Average click rate','12.6%','+2.1%'],['Conversions','54','+18 this month']].map(([label,value,change]) => <div key={label} className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs text-slate-500">{label}</p><p className="mt-2 text-2xl font-semibold">{value}</p><p className="mt-1 text-[11px] text-emerald-600">{change} <ArrowUpRight className="inline size-3" /></p></div>)}</div><div className="mb-4 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-2.5 size-4 text-slate-400" /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search campaigns..." className="h-9 w-full rounded-lg border border-slate-200 bg-white pl-9 pr-3 text-sm outline-none focus:border-indigo-400" /></div><select value={status} onChange={(e) => setStatus(e.target.value as typeof status)} className="h-9 rounded-lg border border-slate-200 bg-white px-3 text-xs"><option>All</option><option>Draft</option><option>Scheduled</option><option>Sent</option><option>Paused</option></select><button onClick={() => notify('Saved audiences opened')} className={smallButton}><Users className="size-3.5" />Audiences</button></div><div className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm"><div className="overflow-x-auto"><table className="w-full min-w-[940px] text-left text-sm"><thead className="bg-slate-50 text-[10px] uppercase tracking-wider text-slate-400"><tr><th className="px-5 py-3">Campaign</th><th className="px-3 py-3">Status</th><th className="px-3 py-3">Audience</th><th className="px-3 py-3">Delivered</th><th className="px-3 py-3">Opens</th><th className="px-3 py-3">Clicks</th><th className="px-3 py-3">Conversions</th><th className="px-3 py-3" /></tr></thead><tbody>{visible.map((campaign) => <tr key={campaign.id} className="border-t border-slate-100"><td className="px-5 py-4"><button onClick={() => notify(`${campaign.name} analytics opened`)} className="text-left"><span className="block font-medium hover:text-indigo-600">{campaign.name}</span><span className="block text-xs text-slate-400">{campaign.subject} · {campaign.sent}</span></button></td><td className="px-3 py-4"><span className={`rounded-full px-2 py-1 text-[10px] font-semibold ${campaign.status === 'Sent' ? 'bg-emerald-50 text-emerald-700' : campaign.status === 'Scheduled' ? 'bg-indigo-50 text-indigo-700' : campaign.status === 'Paused' ? 'bg-amber-50 text-amber-700' : 'bg-slate-100 text-slate-600'}`}>{campaign.status}</span></td><td className="px-3 py-4 text-slate-600">{campaign.audience}</td><td className="px-3 py-4">{campaign.delivered ? `${campaign.delivered}%` : '—'}</td><td className="px-3 py-4">{campaign.opens ? `${campaign.opens}%` : '—'}</td><td className="px-3 py-4">{campaign.clicks ? `${campaign.clicks}%` : '—'}</td><td className="px-3 py-4 font-medium">{campaign.conversions || '—'}</td><td className="px-3 py-4"><button onClick={() => changeStatus(campaign)} className="text-xs font-medium text-indigo-600">{campaign.status === 'Paused' ? 'Resume' : campaign.status === 'Sent' ? 'Pause' : 'Change status'}</button></td></tr>)}</tbody></table></div>{visible.length === 0 && <div className="p-12 text-center"><Mail className="mx-auto size-8 text-slate-300" /><p className="mt-3 text-sm font-medium">No campaigns found</p></div>}</div><div className="mt-6 grid gap-4 lg:grid-cols-[1.15fr_.85fr]"><div className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="text-sm font-semibold">Campaign performance</h2><p className="mt-1 text-xs text-slate-400">Engagement over the last 30 days</p></div><button onClick={() => notify('Analytics exported')} className={smallButton}><Download className="size-3.5" />Export</button></div><div className="mt-5 flex h-32 items-end gap-2">{[42,58,52,71,63,82,76,92,68,88,74,96].map((height,index) => <div key={index} className="flex flex-1 flex-col items-center gap-2"><div className="w-full rounded-t-md bg-indigo-200 hover:bg-indigo-500" style={{ height: `${height}%` }} /><span className="text-[9px] text-slate-400">W{index % 4 + 1}</span></div>)}</div></div><div className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><h2 className="text-sm font-semibold">Saved audiences</h2><div className="mt-4 flex flex-col gap-2">{[['Active customers','1,284'],['Enterprise accounts','184'],['Newsletter subscribers','3,842'],['Dormant contacts','426']].map(([label,count]) => <button key={label} onClick={() => notify(`${label} selected`)} className="flex items-center justify-between rounded-lg border border-slate-100 px-3 py-2.5 text-left text-xs hover:border-indigo-200"><span className="flex items-center gap-2 font-medium"><Users className="size-3.5 text-indigo-500" />{label}</span><span className="text-slate-400">{count}</span></button>)}</div><button onClick={() => notify('New segment form opened')} className="mt-4 w-full rounded-lg border border-dashed border-slate-300 py-2 text-xs font-semibold text-indigo-600">+ Create segment</button></div></div>{wizard && <Modal title={`Create campaign · ${step + 1} of 4`} onClose={() => setWizard(false)}><div className="mb-5 flex gap-1">{['Basics','Audience','Design','Review'].map((label,index) => <div key={label} className={`h-1.5 flex-1 rounded-full ${index <= step ? 'bg-indigo-600' : 'bg-slate-100'}`} />)}</div>{step === 0 && <div className="flex flex-col gap-4"><label className="text-xs font-medium">Campaign name<input value={draft.name} onChange={(e) => setDraft({ ...draft,name:e.target.value })} placeholder="November product update" className="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm" /></label><label className="text-xs font-medium">Subject line<input value={draft.subject} onChange={(e) => setDraft({ ...draft,subject:e.target.value })} placeholder="Write a clear subject line" className="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm" /></label><label className="text-xs font-medium">Sender<select value={draft.sender} onChange={(e) => setDraft({ ...draft,sender:e.target.value })} className="mt-1.5 h-10 w-full rounded-lg border border-slate-200 px-3 text-sm"><option>Ahmed Raza</option><option>Lifecycle team</option><option>Marketing team</option></select></label></div>}{step === 1 && <div className="flex flex-col gap-3"><p className="text-xs text-slate-500">Select a saved audience or create a segment.</p>{['Active customers','Enterprise accounts','Newsletter subscribers','Dormant contacts'].map((audience) => <button key={audience} onClick={() => setDraft({ ...draft,audience })} className={`flex items-center justify-between rounded-xl border p-3 text-left ${draft.audience === audience ? 'border-indigo-400 bg-indigo-50' : 'border-slate-200'}`}><span className="text-sm font-medium">{audience}</span><span className="text-xs text-slate-400">{audience === 'Enterprise accounts' ? '184 contacts' : '1,284 contacts'}</span></button>)}</div>}{step === 2 && <div><p className="mb-3 text-xs text-slate-500">Choose a template, then customize editable blocks.</p><div className="grid grid-cols-2 gap-2">{['Product update','Newsletter','Event invite','Plain text'].map((template) => <button key={template} onClick={() => notify(`${template} template selected`)} className="rounded-xl border border-slate-200 p-3 text-left hover:border-indigo-300"><div className="mb-3 h-12 rounded-lg bg-gradient-to-br from-indigo-100 to-slate-100" /><p className="text-xs font-semibold">{template}</p><p className="mt-1 text-[10px] text-slate-400">Text · image · button</p></button>)}</div><div className="mt-3 rounded-xl border border-dashed border-indigo-200 bg-indigo-50 p-3 text-xs text-indigo-700">Drag-and-drop style editor: click blocks to edit copy, images, buttons, and layout sections.</div></div>}{step === 3 && <div className="flex flex-col gap-3"><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs text-slate-400">Subject</p><p className="mt-1 font-semibold">{draft.subject || 'Add a subject line'}</p><p className="mt-3 text-xs text-slate-400">Audience</p><p className="mt-1 font-semibold">{draft.audience}</p><p className="mt-3 text-xs text-slate-400">Sender</p><p className="mt-1 font-semibold">{draft.sender}</p></div><div className="flex gap-2"><button onClick={() => notify('Desktop preview opened')} className={smallButton}>Desktop preview</button><button onClick={() => notify('Mobile preview opened')} className={smallButton}>Mobile preview</button></div></div>}<div className="mt-6 flex justify-between border-t border-slate-100 pt-4"><button onClick={() => step === 0 ? saveDraft() : setStep(step - 1)} className={smallButton}>{step === 0 ? 'Save draft' : 'Back'}</button>{step < 3 ? <button onClick={() => { if (step === 0 && (!draft.name.trim() || !draft.subject.trim())) { notify('Complete required fields'); return } setStep(step + 1) }} className="rounded-lg bg-indigo-600 px-4 py-2 text-xs font-semibold text-white">Continue</button> : <button onClick={saveDraft} className="rounded-lg bg-indigo-600 px-4 py-2 text-xs font-semibold text-white">Save campaign</button>}</div></Modal>}</div>
}

